toad_implementation.code_blueprint:
canvas {
  size: 960px 650px;
  fill: #18191C;
  font-family: "Courier Prime, monospace";
}

>corkWall = #18191C;
>redString = #DC2626;
>cardWhite = #F8FAFC;
>darkInk = #0F172A;

text #caseHeader {
  at: top left of canvas offset 40px 32px;
  content: "EVIDENCE BOARD // OPERATION NIGHTSHADE";
  font-size: 16px;
  font-weight: 700;
  color: >redString;
}

rect #stringCenterLeft {
  at: center of canvas offset -140px -40px;
  size: 260px 3px;
  fill: >redString;
}

rect #suspectCardMain {
  at: center of canvas offset 0px -40px;
  size: 200px 240px;
  fill: >cardWhite;
  radius: 2px;
}

circle #pinMain {
  at: top center of #suspectCardMain offset 0px 10px;
  size: 12px;
  fill: >redString;
}

text #suspectName {
  at: center of #suspectCardMain;
  content: "SUBJECT ALPHA\n[PRIME TARGET]";
  font-size: 14px;
  font-weight: 700;
  color: >darkInk;
}

rect #evidenceCardLeft {
  at: left of #suspectCardMain offset -180px 0px;
  size: 160px 180px;
  fill: >cardWhite;
  radius: 2px;
}

text #evidenceText {
  at: center of #evidenceCardLeft;
  content: "EXHIBIT B\nCCTV FOOTAGE\n02:14 AM";
  font-size: 12px;
  color: >darkInk;
}
